const state={data:null,period:"1",action:"all"};
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const money=n=>{const a=Math.abs(Number(n||0));return `${Number(n)>=0?"+":"−"}${a>=1e8?(a/1e8).toFixed(2)+" 億":a>=1e4?(a/1e4).toFixed(1)+" 萬":Math.round(a).toLocaleString()}`};
const lots=n=>`${(Math.abs(Number(n||0))/1000).toLocaleString("zh-TW",{maximumFractionDigits:1})} 張`;
const pct=n=>`${(Number(n||0)*100).toFixed(0)}%`;
const cls=n=>Number(n)>=0?"up":"down";
function renderSummary(){const rows=state.data.core_stocks;const t=state.data.portfolio_totals||{};const count=c=>rows.filter(r=>c.includes(r.action_code)).length;$("#summary").innerHTML=`<article><small>總可觀察庫存</small><strong>${Number(t.inventory_lots||0).toLocaleString("zh-TW",{maximumFractionDigits:1})}</strong><span>張 · ${t.stock?0:t.stock_count||0} 檔</span></article><article><small>總庫存市值</small><strong class="up">${money(t.market_value).replace(/^[+−]/,"")}</strong><span>依最新收盤估算</span></article><article><small>近 20 日淨投入</small><strong class="${cls(t.rolling_20d_net_invested)}">${money(t.rolling_20d_net_invested)}</strong><span>宏遠 1260 資金流</span></article><article><small>核心觀察</small><strong>${rows.length}</strong><span>檔股票</span></article><article><small>新建／加碼</small><strong class="up">${count(["new","add"])}</strong><span>資金擴張</span></article><article><small>減碼／出清</small><strong class="down">${count(["trim","reduce","exit"])}</strong><span>留意退潮</span></article>`}
function renderCore(){let rows=state.data.core_stocks;if(state.action!=="all"){const wanted=state.action.split(",");rows=rows.filter(r=>wanted.includes(r.action_code))}$("#empty").hidden=rows.length>0;$("#core-list").innerHTML=rows.map((r,i)=>`<article class="stock"><div class="rank">${String(i+1).padStart(2,"0")}</div><div class="stock-main"><div class="stock-title"><div><b>${r.stock_name}</b><small>${r.stock_id}</small></div><span class="tag ${r.action_code}">${r.action_label}</span></div><div class="grid"><span><small>收盤</small><b>${Number(r.close).toLocaleString()}</b></span><span><small>今日淨額</small><b class="${cls(r.net_amount_1)}">${money(r.net_amount_1)}</b></span><span><small>5 日</small><b class="${cls(r.net_amount_5)}">${money(r.net_amount_5)}</b></span><span><small>10 日</small><b class="${cls(r.net_amount_10)}">${money(r.net_amount_10)}</b></span><span><small>20 日</small><b class="${cls(r.net_amount_20)}">${money(r.net_amount_20)}</b></span><span><small>庫存留存</small><b>${pct(r.inventory_retention)}</b></span></div><div class="bar"><i style="width:${Math.min(100,Number(r.core_score||0))}%"></i></div><p>可觀察庫存 ${lots(r.inventory)} · 市值 ${money(r.market_value).replace(/^[+−]/,"")} · 核心分數 ${r.core_score}</p></div></article>`).join("")}
function renderFlow(){const rows=state.data.flow_windows[state.period]||[];const buy=rows.filter(r=>r.net_amount>0).sort((a,b)=>b.net_amount-a.net_amount).slice(0,12);const sell=rows.filter(r=>r.net_amount<0).sort((a,b)=>a.net_amount-b.net_amount).slice(0,12);const card=r=>`<article><div><b>${r.stock_name}</b><small>${r.stock_id} · ${lots(r.net_vol)}</small></div><strong class="${cls(r.net_amount)}">${money(r.net_amount)}</strong></article>`;$("#buyers").innerHTML=buy.map(card).join("")||"<p class='none'>本期無買超</p>";$("#sellers").innerHTML=sell.map(card).join("")||"<p class='none'>本期無賣超</p>";$("#period-label").textContent=state.period==="1"?"每日":`${state.period} 日`}
all("[data-action]").forEach(b=>b.onclick=()=>{state.action=b.dataset.action;all("[data-action]").forEach(x=>x.classList.toggle("active",x===b));renderCore()});
all("[data-period]").forEach(b=>b.onclick=()=>{state.period=b.dataset.period;all("[data-period]").forEach(x=>x.classList.toggle("active",x===b));renderFlow()});
fetch("./data/snapshot.json",{cache:"no-store"}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{state.data=d;$("#fresh").textContent=`資料日 ${d.as_of.slice(0,4)}.${d.as_of.slice(4,6)}.${d.as_of.slice(6)}`;$("#threshold").textContent=`NT$ ${money(d.threshold).replace("+","")}`;$("#method").textContent=d.method_note;renderSummary();renderCore();renderFlow()}).catch(()=>{$("#fresh").textContent="資料讀取失敗";$("#core-list").innerHTML="<p class='none'>請先執行每日更新。</p>"});
